def extend_diagonal_runs(grid):
    """Extend every diagonal run of two or more same-colored non-background cells at both ends through background cells."""
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for dr, dc in ((1, 1), (1, -1)):
        for i in range(h):
            for j in range(w):
                c = grid[i][j]
                if c == bg:
                    continue
                ni, nj = i + dr, j + dc
                if 0 <= ni < h and 0 <= nj < w and grid[ni][nj] == c:
                    pi, pj = i - dr, j - dc
                    if not (0 <= pi < h and 0 <= pj < w and grid[pi][pj] == c):
                        # run head: extend backwards
                        r, s = i - dr, j - dc
                        while 0 <= r < h and 0 <= s < w and out[r][s] == bg:
                            out[r][s] = c
                            r -= dr; s -= dc
                    qi, qj = i + dr, j + dc
                    if not (0 <= qi < h and 0 <= qj < w and grid[qi][qj] == c):
                        r, s = i + dr, j + dc
                        while 0 <= r < h and 0 <= s < w and out[r][s] == bg:
                            out[r][s] = c
                            r += dr; s += dc
    return out

